const CATARACT_INFO={id:"cataract-surgery",title:"Sushruta's Cataract Surgery",originRegion:"Ancient India (Varanasi region)",eraOrigin:"c. 6th Century BCE",quickStats:[{label:"Physician",value:"Sushruta",icon:"👨‍⚕️"},{label:"Text",value:"Sushruta Samhita",icon:"📜"},{label:"Era",value:"c. 6th Century BCE",icon:"🏺"},{label:"Field",value:"Early Ophthalmology & Surgery",icon:"👁️"},{label:"Historical Term",value:"Couching",icon:"📖"},{label:"Legacy",value:"Foundational text of Ayurvedic surgery",icon:"🌍"}]},HISTORY_TEXT={title:"Sushruta and the Sushruta Samhita",paragraphs:["Sushruta was an ancient Indian physician, often regarded as one of the earliest documented surgeons in recorded history. He is credited as the principal author of the Sushruta Samhita, a foundational Sanskrit text on medicine and surgery composed around the 6th century BCE, and a cornerstone of the Ayurvedic medical tradition.","The Sushruta Samhita is historically notable for describing a technique for treating cataract-related blindness — a condition long recognized across ancient civilizations. This technique, later referred to in historical literature as 'couching,' is one of the earliest documented surgical approaches to vision impairment anywhere in the world.","Beyond ophthalmology, the Sushruta Samhita covers a remarkably broad range of surgical topics for its time, including wound care, instruments, and classifications of surgical procedures, and it discusses principles of patient examination and pre-operative assessment that were advanced for the ancient world.","Historians of medicine regard Sushruta's work as a significant milestone in the global history of surgery, influencing medical thought in South Asia for centuries and later drawing the interest of medical historians studying the origins of ophthalmic treatment worldwide."]},TIMELINE_EVENTS=[{era:"c. 6th Century BCE",title:"Sushruta Samhita Composed",description:"Sushruta's foundational text describes early surgical thought and references treatment of vision impairment caused by cataracts, in the context of ancient Indian medicine."},{era:"c. 1st Millennium CE",title:"Spread Across South Asia",description:"Ayurvedic surgical knowledge, including Sushruta's teachings, continued to circulate and be studied across the Indian subcontinent for centuries."},{era:"Medieval Period",title:"Cross-Cultural Exchange",description:"Historical scholarship suggests ancient Indian medical knowledge influenced, and was influenced by, medical traditions in the Middle East and parts of Asia through trade and scholarly exchange."},{era:"18th–19th Century CE",title:"European Encounter with Ayurvedic Texts",description:"Colonial-era scholars and physicians began translating and studying Ayurvedic medical texts, including the Sushruta Samhita, bringing renewed historical attention to ancient Indian surgical thought."},{era:"20th Century CE",title:"Modern Cataract Surgery Develops",description:"Advances in anesthesia, sterile technique, optics, and microsurgery led to the safe, precise modern cataract procedures used in ophthalmology today."},{era:"Today",title:"Recognized Historical Milestone",description:"Medical historians widely cite Sushruta's work as an important early chapter in the global history of surgery and ophthalmology."}],COMPARISON_ROWS=[{aspect:"Historical Context",ancient:"Practiced within the framework of ancient Ayurvedic medicine, described in Sanskrit texts",modern:"Practiced within evidence-based, regulated ophthalmology"},{aspect:"Understanding of the Eye",ancient:"Based on the anatomical and medical knowledge available in ancient India",modern:"Informed by modern optics, microbiology, and anatomy"},{aspect:"Safety Standards",ancient:"No modern anesthesia, sterilization, or antibiotics existed",modern:"Governed by strict sterile technique, anesthesia, and safety protocols"},{aspect:"Tools",ancient:"Hand-made instruments described in classical texts",modern:"Precision microsurgical and laser-assisted instruments"},{aspect:"Documentation",ancient:"Recorded in the Sushruta Samhita as part of a broader medical treatise",modern:"Documented through peer-reviewed clinical research"},{aspect:"Historical Significance",ancient:"One of the earliest known references to surgical treatment of vision loss",modern:"Built on centuries of accumulated global medical knowledge"}],SIGNIFICANCE_POINTS=[{title:"Early Surgical Documentation",description:"The Sushruta Samhita is among the oldest surviving texts to systematically document surgical thought, making it a landmark in the history of medicine."},{title:"Foundational to Ayurveda",description:"Sushruta's work remains one of the core classical texts of Ayurvedic medicine, studied historically and academically for over two millennia."},{title:"Global Historical Interest",description:"Historians of medicine worldwide reference Sushruta's descriptions when tracing the early history of ophthalmology and surgery."},{title:"Cultural Heritage",description:"The text reflects the sophistication of scientific and medical thought in ancient India, and is regarded as part of India's intellectual heritage."}],REFERENCES=[{text:"Bhishagratna, K. K. — 'The Sushruta Samhita' (English translation).",link:"#"},{text:"Loukas, M. et al. — historical reviews on Sushruta's contributions to surgery.",link:"#"},{text:"National Institutes of Health (NIH) — historical articles on the history of cataract surgery.",link:"#"},{text:"Wellcome Collection — resources on the history of Ayurvedic medicine.",link:"#"}];